def test_Course_add_student__unit_3():
    course = Course("History", capacity=1)
    student1 = "Charlie"
    course.add_student(student1)
    student2 = "Dana"
    with pytest.raises(ValueError, match="course is full"):
        course.add_student(student2)
    assert len(course.students) == 1
    assert student1 in course.students
